using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class SettingsTests {
 static int count;static void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);count++;}
 static void Reject(Action action,string label){bool ok=false;try{action();}catch(IOException){ok=true;}Check(ok,label);}
 static string Stage(string root,params string[] relative){string id=Guid.NewGuid().ToString("N"),dir=Path.Combine(root,id);Directory.CreateDirectory(Path.Combine(dir,"payload"));var plan=new SettingsPlan{Id=id};for(int i=0;i<relative.Length;i++){byte[] data=Encoding.UTF8.GetBytes("[Graphics]\nQuality="+(i+2));File.WriteAllBytes(Path.Combine(dir,"payload",i+".txt"),data);plan.Files.Add(new SettingsFile{Relative=relative[i],Hash=SettingsTransfer.Hash(data),Size=data.Length});}File.WriteAllText(Path.Combine(dir,"request.json"),new JavaScriptSerializer().Serialize(plan));return dir;}
 public static int Main(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Verification","SettingsTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
  Check(SettingsTransfer.Candidate(@"Config\WindowsClient\GameUserSettings.ini"),"generic engine settings recognized");Check(!SettingsTransfer.Candidate(@"SaveGames\settings.json")&&!SettingsTransfer.Candidate("login_settings.json")&&!SettingsTransfer.Candidate("settings.exe")&&!SettingsTransfer.Candidate("GameUserSettings_2535405420118952.ini"),"save, account and executable paths excluded");
  SettingsTransfer.ValidateText(Encoding.UTF8.GetBytes("{\"graphics\":\"high\"}"));Check(true,"ordinary text settings accepted");Reject(()=>SettingsTransfer.ValidateText(new byte[]{0,1,2,3}),"binary payload rejected");Reject(()=>SettingsTransfer.ValidateText(Encoding.UTF8.GetBytes("{\"access_token\":\"secret\"}")),"credential fields rejected");Reject(()=>SettingsTransfer.ValidateText(Encoding.UTF8.GetBytes("{\"progression\":123}")),"progress fields rejected");Reject(()=>SettingsTransfer.ValidateText(Encoding.UTF8.GetBytes("<settings><password>secret</password></settings>")),"XML credential fields rejected");SettingsTransfer.ValidateText(Encoding.Unicode.GetPreamble().Concat(Encoding.Unicode.GetBytes("quality=high")).ToArray());Check(true,"BOM-marked UTF-16 settings accepted");
  string profile=Path.Combine(root,"profile"),history=Path.Combine(root,"history");Directory.CreateDirectory(profile);Reject(()=>SettingsTransfer.Within(profile,@"..\escape.ini"),"traversal rejected");Reject(()=>SettingsTransfer.Within(profile,@"AppData\Local\ExampleGame.\settings.ini"),"ambiguous trailing-dot destination rejected");Reject(()=>SettingsTransfer.Within(profile,@"AppData\Local\NUL\settings.ini"),"Windows device destination rejected");Reject(()=>SettingsTransfer.Destination(profile,@"AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup\settings.ini"),"Windows startup destination rejected");Reject(()=>SettingsTransfer.Destination(profile,@"Client\config\settings.ini"),"launcher destination rejected");
  string relative=@"AppData\Local\ExampleGame\Config\settings.ini",created=@"AppData\Local\ExampleGame\Config\input.ini",target=SettingsTransfer.Destination(profile,relative);Directory.CreateDirectory(Path.GetDirectoryName(target));File.WriteAllText(target,"original settings");string stage=Stage(root,relative,created);SettingsTransfer.Apply(stage,profile,history);Check(File.ReadAllText(target).Contains("Quality=2")&&File.Exists(SettingsTransfer.Destination(profile,created)),"selected existing and new files copied");
  File.WriteAllText(target,"newer user settings");Reject(()=>SettingsTransfer.Restore(profile,history),"restore preserves newer user changes");File.WriteAllBytes(target,File.ReadAllBytes(Path.Combine(stage,"payload","0.txt")));SettingsTransfer.Restore(profile,history);Check(File.ReadAllText(target)=="original settings"&&!File.Exists(SettingsTransfer.Destination(profile,created)),"restore returns original file and removes newly imported file");Reject(()=>SettingsTransfer.Restore(profile,history),"repeat restore rejected");
  string bad=Stage(root,relative);File.AppendAllText(Path.Combine(bad,"payload","0.txt"),"tampered");Reject(()=>SettingsTransfer.Apply(bad,profile,history),"changed staged data rejected before writes");Check(File.ReadAllText(target)=="original settings","rejected import leaves destination unchanged");
  bad=Stage(root,relative,relative);Reject(()=>SettingsTransfer.Apply(bad,profile,history),"duplicate destination rejected");
  string blocked=@"AppData\Local\ExampleGame\Config\blocked.ini";Directory.CreateDirectory(SettingsTransfer.Destination(profile,blocked));bad=Stage(root,relative,blocked);bool failed=false;try{SettingsTransfer.Apply(bad,profile,history);}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(target)=="original settings","failed multi-file import rolls back earlier changes");
  string game=Path.Combine(root,@"steamapps\common\TestGame"),custom=Path.Combine(root,"Manual Settings");Directory.CreateDirectory(game);Directory.CreateDirectory(custom);File.WriteAllText(Path.Combine(root,@"steamapps\appmanifest_123.acf"),"\"AppState\" { \"appid\" \"123\" \"name\" \"Test Game\" \"installdir\" \"TestGame\" }");File.WriteAllText(Path.Combine(custom,"settings.ini"),"quality=high");File.WriteAllText(Path.Combine(custom,"savegame.json"),"{}");File.WriteAllText(Path.Combine(custom,"account_settings.json"),"{}");File.WriteAllText(Path.Combine(custom,"graphics.json"),"{\"password\":\"secret\"}");Directory.CreateDirectory(Path.Combine(custom,@"Saved\Config\WindowsClient"));File.WriteAllText(Path.Combine(custom,@"Saved\Config\WindowsClient\engine.ini"),"quality=high");var scan=SettingsScanner.Scan(game,custom);Check(scan.AppId=="123"&&scan.Name=="Test Game","selected installation identified from its Steam manifest");Check(scan.Files.Count==2&&scan.Files.Any(f=>f.Source.Contains(@"Saved\Config"))&&scan.Files.All(f=>!f.Selected),"manual scan offers only eligible files and selects nothing automatically");
  Check(DualSteamNative.SteamTaskbarIdentity.ManagerId!=DualSteamNative.SteamTaskbarIdentity.SecondSteamId,"manager and Second Steam have distinct taskbar identities");Console.WriteLine(count+" settings checks passed.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}
